package postgres

import (
	"context"
	"fmt"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/manovaspace/orbit-notifications/internal/domain"
	"github.com/manovaspace/orbit-notifications/internal/infrastructure/postgres/sqlcgen"
)

// Repository implements domain.Store on Postgres. Every statement it runs is
// generated by sqlc from queries/delivery_records.sql.
type Repository struct {
	queries *sqlcgen.Queries
}

// NewRepository builds the store on a pgx pool.
func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{queries: sqlcgen.New(pool)}
}

// Insert writes one delivery record.
func (r *Repository) Insert(ctx context.Context, record domain.DeliveryRecord) error {
	id, err := uuid.Parse(record.ID)
	if err != nil {
		return fmt.Errorf("postgres: delivery id %q: %w", record.ID, err)
	}
	var devPayload *string
	if record.DevPayload != "" {
		devPayload = &record.DevPayload
	}
	createdAt := pgtype.Timestamptz{}
	if !record.CreatedAt.IsZero() {
		createdAt = pgtype.Timestamptz{Time: record.CreatedAt, Valid: true}
	}
	return r.queries.InsertDelivery(ctx, sqlcgen.InsertDeliveryParams{
		ID:            id,
		Template:      record.Template,
		Channel:       record.Channel,
		RecipientHash: record.RecipientHash,
		Status:        record.Status,
		DevPayload:    devPayload,
		CorrelationID: record.CorrelationID,
		CreatedAt:     createdAt,
	})
}

// List returns the most recent delivery records, newest first.
func (r *Repository) List(ctx context.Context, limit int, channel string) ([]domain.DeliveryRecord, error) {
	var channelFilter *string
	if channel != "" {
		channelFilter = &channel
	}
	rows, err := r.queries.ListDeliveries(ctx, sqlcgen.ListDeliveriesParams{
		Channel: channelFilter,
		Limit:   int32(limit), // the application clamps the limit to 1..100
	})
	if err != nil {
		return nil, err
	}
	out := make([]domain.DeliveryRecord, 0, len(rows))
	for _, row := range rows {
		out = append(out, domain.DeliveryRecord{
			ID:            row.ID,
			Template:      row.Template,
			Channel:       row.Channel,
			RecipientHash: row.RecipientHash,
			Status:        row.Status,
			DevPayload:    row.DevPayload,
			CorrelationID: row.CorrelationID,
			CreatedAt:     row.CreatedAt.Time,
		})
	}
	return out, nil
}
